sn_aia_tool.script:
(function(inputs) {
    /* AI agent tool "Submit manager support request" (Manager Team Brief Assistant).
     * Submits the Request Manager Support record producer with the values the manager
     * confirmed in chat, so the request goes through the same producer script, approval and flow as the portal.
     * Runs as the logged-in manager. */
    var PRODUCER = 'fb03c7671b7b0750b2f70fa0604bcb24';
    var me = gs.getUserID();

    // Team member: only the manager's own active direct reports (same rule as the producer's reference qualifier)
    var member = new GlideRecord('sys_user');
    member.addActiveQuery();
    member.addQuery('manager', me);
    member.addQuery('name', String(inputs.team_member || '').trim());
    member.query();
    if (!member.next())
        return { status: 'error', message: 'Team member must be one of your own direct reports.' };

    // Request type: accept the label ("Onboarding support") or the value ("onboarding_support")
    var type = String(inputs.request_type || '').trim();
    var choice = new GlideRecord('sys_choice');
    choice.addQuery('name', 'x_snp_manager_su_0_manager_support_request');
    choice.addQuery('element', 'request_type');
    choice.addQuery('inactive', false);
    choice.addQuery('label', type).addOrCondition('value', type);
    choice.query();
    if (!choice.next())
        return { status: 'error', message: 'Unknown request type: ' + type };

    // Due date: yyyy-MM-dd, or the manager's own date format
    var due = String(inputs.due_date || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) {
        var gd = new GlideDate();
        gd.setDisplayValue(due);
        due = gd.getValue();
    }
    var summary = String(inputs.summary || '').trim();
    if (!due || !summary)
        return { status: 'error', message: 'Due date and Summary are required.' };

    var result = new sn_sc.CartJS().submitProducer({
        sysparm_id: PRODUCER,
        variables: {
            subject_person: member.getUniqueValue(),
            request_type: choice.getValue('value'),
            due_date: due,
            short_description: summary
        }
    });
    return { status: 'success', number: result.number, record_id: result.sys_id, table: result.table };
})(inputs);
